using System;using Ossastra.CharacterCore;
class ComboTests{static void Main(){var constructor=typeof(BasicChainState).GetConstructor(new[]{typeof(double),typeof(double),typeof(double),typeof(int)});if(constructor==null)throw new Exception("chain still fixed to two stages");var chain=(BasicChainState)constructor.Invoke(new object[]{.12,.17,.45,4});for(int stage=1;stage<=4;stage++){var time=stage*.2;var expected=stage==1?1:stage;if(chain.Request(time,true,true)!=expected)throw new Exception("stage "+stage);var id=Guid.NewGuid();chain.Accepted(stage,id,time,.1);chain.Hit(id,true);}if(chain.Request(5,true,true)!=1)throw new Exception("final wraps");Console.WriteLine("5 configurable combo contracts passed");}}
